import os, re, glob

ocr_files = sorted(glob.glob('/app/ocr_kf/*.txt'), key=lambda x: float(re.search(r'(\d+\.\d+)\.txt', x).group(1)))

def read_text(fpath):
    with open(fpath, 'r', errors='replace') as f:
        return f.read()

def get_gt_commands(text):
    lines = text.splitlines()
    cmds = []
    for l in lines:
        ls = l.strip()
        if ls.startswith('>'):
            cmd = ls[1:].strip()
            if cmd and len(cmd) < 80:
                cmds.append(cmd)
    return cmds

# For each keyframe, get the last '>' command
